import{_ as o,C as r,o as a,c as s,a0 as t,b as c,w as i,a as l,E as d,a1 as u}from"./chunks/framework.DYS8d9tm.js";const y=JSON.parse('{"title":"Email Ingestion & Hardened Sync System","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/email_ingestion.md","filePath":"technical/data ingestion/email_ingestion.md"}'),g={name:"technical/data ingestion/email_ingestion.md"};function m(h,e,p,S,A,_){const n=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="email-ingestion-hardened-sync-system" tabindex="-1">Email Ingestion &amp; Hardened Sync System <a class="header-anchor" href="#email-ingestion-hardened-sync-system" aria-label="Permalink to &quot;Email Ingestion &amp; Hardened Sync System&quot;">​</a></h1><h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>The Email Ingestion System provides a high-reliability bridge between financial email sources (bank alerts, statements) and the core finance engine. This document serves as both the architectural overview and technical specification for the hardened sync pipeline.</p><h2 id="_2-architecture-data-flow" tabindex="-1">2. Architecture &amp; Data Flow <a class="header-anchor" href="#_2-architecture-data-flow" aria-label="Permalink to &quot;2. Architecture &amp; Data Flow&quot;">​</a></h2>',4)),(a(),c(u,null,{default:i(()=>[d(n,{id:"mermaid-12",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20UI%20as%20Frontend%20(EmailSettings.vue)%0A%20%20%20%20participant%20API%20as%20Backend%20API%20(router.py)%0A%20%20%20%20participant%20SCH%20as%20Scheduler%20(scheduler.py)%0A%20%20%20%20participant%20ESS%20as%20EmailSyncService%0A%20%20%20%20participant%20SP%20as%20StatementProcessor%0A%20%20%20%20participant%20PS%20as%20External%20Parser%20Service%0A%20%20%20%20participant%20DB%20as%20Database%20(EmailSyncLog)%0A%0A%20%20%20%20rect%20rgb(240%2C%20248%2C%20255)%0A%20%20%20%20Note%20over%20UI%2C%20API%3A%20User%20Interaction%0A%20%20%20%20UI-%3E%3EAPI%3A%20POST%20%2Femail%2Fsync%2F%7Bid%7D%0A%20%20%20%20API--%3E%3EUI%3A%20200%20OK%20(Status%3A%20Started)%0A%20%20%20%20end%0A%0A%20%20%20%20par%20Background%20Execution%20(Transactions)%0A%20%20%20%20%20%20%20%20API-%3E%3EESS%3A%20sync_emails()%0A%20%20%20%20%20%20%20%20ESS-%3E%3EESS%3A%20Fetch%20IMAP%20UIDs%0A%20%20%20%20%20%20%20%20ESS-%3E%3EESS%3A%20Check%20User%20Ignore%20Rules%0A%20%20%20%20%20%20%20%20ESS-%3E%3EESS%3A%20Clean%20HTML%20(Preserve%20%5Cn)%0A%20%20%20%20%20%20%20%20ESS-%3E%3EPS%3A%20Batch%20Extract%0A%20%20%20%20%20%20%20%20PS--%3E%3EESS%3A%20Results%0A%20%20%20%20%20%20%20%20ESS-%3E%3EDB%3A%20Log%20raw_content%20%2B%20outcome%20JSON%0A%20%20%20%20and%20Background%20Execution%20(Statements)%0A%20%20%20%20%20%20%20%20API-%3E%3ESP%3A%20sync_statements()%0A%20%20%20%20%20%20%20%20SP-%3E%3ESP%3A%20Broad%20IMAP%20Search%0A%20%20%20%20%20%20%20%20SP-%3E%3ESP%3A%20Extract%20PDF%0A%20%20%20%20%20%20%20%20SP-%3E%3EPS%3A%20Parse%20Statement%0A%20%20%20%20%20%20%20%20SP-%3E%3EDB%3A%20Log%20Detailed%20JSON%0A%20%20%20%20end%0A%0A%20%20%20%20UI-%3E%3EDB%3A%20Fetch%20Ingestions%20Feed%20%2F%20Sync%20Logs%0A%20%20%20%20DB--%3E%3EUI%3A%20JSON%20Data%0A%20%20%20%20UI-%3E%3EUI%3A%20Render%20Full%20Content%20%26%20Outcome%20Details%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="_3-technical-specifications" tabindex="-1">3. Technical Specifications <a class="header-anchor" href="#_3-technical-specifications" aria-label="Permalink to &quot;3. Technical Specifications&quot;">​</a></h2><h3 id="_3-1-imap-stability-uid-based-sync" tabindex="-1">3.1 IMAP Stability (UID-Based Sync) <a class="header-anchor" href="#_3-1-imap-stability-uid-based-sync" aria-label="Permalink to &quot;3.1 IMAP Stability (UID-Based Sync)&quot;">​</a></h3><p>Standard IMAP sequence numbers are volatile and reset upon mailbox re-indexing. The system now uses <strong>IMAP UIDs</strong>, which are persistent unique identifiers. This ensures that the system&#39;s &quot;last synced&quot; pointer remains accurate even if the user moves or deletes emails in their provider&#39;s UI.</p><h3 id="_3-2-html-cleaning-pre-extraction-ignore-filtering" tabindex="-1">3.2 HTML Cleaning &amp; Pre-Extraction Ignore Filtering <a class="header-anchor" href="#_3-2-html-cleaning-pre-extraction-ignore-filtering" aria-label="Permalink to &quot;3.2 HTML Cleaning &amp; Pre-Extraction Ignore Filtering&quot;">​</a></h3><p>Bank emails often use complex nested tables. Aggressive tag-stripping typically results in a single-line string that regex extractors cannot process.</p><ul><li><strong>Layout Preservation</strong>: The cleaner replaces <code>&lt;tr&gt;</code>, <code>&lt;br&gt;</code>, <code>&lt;p&gt;</code>, and <code>&lt;div&gt;</code> tags with <code>\\n</code> before stripping remaining HTML.</li><li><strong>Pre-Extraction Ignore Rules</strong>: Before calling the extraction microservice, <code>EmailSyncService</code> evaluates <code>IngestionService.check_ignore_rules()</code> against the tenant&#39;s <code>SpamFilter</code> and <code>IgnoredPattern</code> rules, immediately discarding matched mail while logging <code>outcome = &quot;ignored_by_rule&quot;</code> so users can later unblock via <strong>Allow</strong>.</li><li><strong>Strict Non-Financial Classification</strong>: <code>FinancialClassifier.is_financial(..., source=&quot;EMAIL&quot;)</code> plus structured bank parsers filter out promotional offers, cashbacks, and OTP alerts.</li></ul><h3 id="_3-3-sender-normalization-routing" tabindex="-1">3.3 Sender Normalization &amp; Routing <a class="header-anchor" href="#_3-3-sender-normalization-routing" aria-label="Permalink to &quot;3.3 Sender Normalization &amp; Routing&quot;">​</a></h3><p>Email &quot;From&quot; headers are normalized to a clean format (lowercase email only) to ensure reliable routing to custom bank-specific handlers:</p><ul><li><strong>Raw</strong>: <code>HDFC Bank &lt;alerts@hdfcbank.net&gt;</code></li><li><strong>Normalized</strong>: <code>alerts@hdfcbank.net</code></li></ul><h2 id="_4-observability-unified-ingestions-sync-activity" tabindex="-1">4. Observability (Unified Ingestions &amp; Sync Activity) <a class="header-anchor" href="#_4-observability-unified-ingestions-sync-activity" aria-label="Permalink to &quot;4. Observability (Unified Ingestions &amp; Sync Activity)&quot;">​</a></h2><p>The system provides granular transparency into every email processed without exposing internal parser class names to end users.</p><h3 id="_4-1-log-hierarchy" tabindex="-1">4.1 Log Hierarchy <a class="header-anchor" href="#_4-1-log-hierarchy" aria-label="Permalink to &quot;4.1 Log Hierarchy&quot;">​</a></h3><ul><li><strong>EmailSyncLog</strong>: Records the overall session (start time, status, total items).</li><li><strong>EmailSyncItemLog</strong>: Records the result for each individual email (<code>raw_content</code>, normalized <code>outcome</code>, sanitized <code>reason</code>, and <code>details_json</code>).</li></ul><h3 id="_4-2-data-points-captured" tabindex="-1">4.2 Data Points Captured <a class="header-anchor" href="#_4-2-data-points-captured" aria-label="Permalink to &quot;4.2 Data Points Captured&quot;">​</a></h3><ul><li><strong>Full Content (<code>raw_content</code>)</strong>: Cleaned email body preserved for user inspection in <strong>Settings → Ingestions</strong>.</li><li><strong>Outcome (<code>outcome</code>)</strong>: Plain-English status (<code>added_to_ledger</code>, <code>moved_to_triage</code>, <code>statement_queued</code>, <code>blocked_unlinked_account</code>, <code>duplicate_skipped</code>, <code>ignored_by_rule</code>, <code>ignored_non_financial</code>, <code>unrecognized_alert</code>).</li><li><strong>Reason (<code>reason</code>)</strong>: Consumer-friendly explanation for what happened to the email.</li><li><strong>Transaction / Account Link</strong>: Direct link to the created <code>Transaction</code>, <code>PendingTransaction</code>, or unlinked account mask.</li></ul><h2 id="_5-unified-parsing-pipeline" tabindex="-1">5. Unified Parsing Pipeline <a class="header-anchor" href="#_5-unified-parsing-pipeline" aria-label="Permalink to &quot;5. Unified Parsing Pipeline&quot;">​</a></h2><p>Email ingestion follows the <a href="./unified_parsing_pipeline.html">Unified Parsing Pipeline</a> priority:</p><ol><li>Registered Bank Parsers</li><li>DB Regex Patterns</li><li>AI Fallback</li></ol><p>Both <strong>Transaction Alerts</strong> and <strong>Statement PDFs</strong> share this underlying extraction engine to ensure consistency across all data sources.</p>',19))])}const P=o(g,[["render",m]]);export{y as __pageData,P as default};
